// Get the binary buffer from the converted PNG
const binaryProperty = 'images_page_1'; // Default binary field name in n8n
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryProperty);

// Format as a complete, clean data URI
return {
  json: {
    dataUrl: `data:image/png;base64,${buffer.toString('base64')}`
  }
};

// Function to safely extract and parse JSON from any nested property or string
function parseDynamicJson(data) {
  // If input is already an object, return it
  if (data && typeof data === 'object') {
    return data;
  }

  if (typeof data === 'string') {
    let cleanText = data.trim();

    // Strip markdown code fences if present (e.g. ```json ... ```)
    cleanText = cleanText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');

    try {
      return JSON.parse(cleanText);
    } catch (e) {
      // Attempt extraction if JSON is embedded inside extra conversational text
      const firstBrace = cleanText.indexOf('{');
      const lastBrace = cleanText.lastIndexOf('}');
      if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
        try {
          return JSON.parse(cleanText.substring(firstBrace, lastBrace + 1));
        } catch (innerErr) {
          // Fallback parsing failed
        }
      }
    }
  }
  return null;
}

// 1. Get raw input from n8n
const input = $input.first().json;

// 2. Resolve target field (handles OpenAI/Qwen responses, direct content, or raw object)
const targetContent = input.choices?.[0]?.message?.content 
                   ?? input.choices?.[0]?.message?.reasoning_content 
                   ?? input.content \
                   ?? input;

// 3. Dynamically parse target into a key-value object
let extractedObj = parseDynamicJson(targetContent);

// Fallback: If no valid JSON was found inside text, retain original input keys
if (!extractedObj || typeof extractedObj !== 'object') {
  extractedObj = input;
}

// 4. Construct final dynamic output with all detected key-values
const normalizedData = {};
for (const [key, value] of Object.entries(extractedObj)) {
  normalizedData[key] = value ?? null;
}

// Return output ready for n8n downstream usage
return [
  {
    json: normalizedData
  }
];
